import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = in.readLine()) != null) {
            all.append(line).append(' ');
        }
        String[] tokens = all.toString().trim().split("\\s+");
        int[] nums = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            nums[i] = Integer.parseInt(tokens[i]);
        }

        int n = nums[0];
        int[] a = { nums[1], nums[2], nums[3] };
        int[] b = { nums[4], nums[5], nums[6] };

        int min = positive(a[0] - b[0] - b[2])
                + positive(a[1] - b[0] - b[1])
                + positive(a[2] - b[1] - b[2]);
        int max = Math.min(a[0], b[1])
                + Math.min(a[1], b[2])
                + Math.min(a[2], b[0]);

        PrintWriter pw = new PrintWriter(System.out);
        pw.println(min + " " + max);
        pw.flush();
    }

    private static int positive(int x) {
        return x > 0 ? x : 0;
    }
}
